macro_rules! nghttp2_recv_callback {
    () => {
        # [doc = " @functypedef"] # [doc = ""] # [doc = " Callback function invoked when |session| wants to receive data from"] # [doc = " the remote peer.  The implementation of this function must read at"] # [doc = " most |length| bytes of data and store it in |buf|.  The |flags| is"] # [doc = " currently not used and always 0.  It must return the number of"] # [doc = " bytes written in |buf| if it succeeds.  If it cannot read any"] # [doc = " single byte without blocking, it must return"] # [doc = " :enum:`NGHTTP2_ERR_WOULDBLOCK`.  If it gets EOF before it reads any"] # [doc = " single byte, it must return :enum:`NGHTTP2_ERR_EOF`.  For other"] # [doc = " errors, it must return :enum:`NGHTTP2_ERR_CALLBACK_FAILURE`."] # [doc = " Returning 0 is treated as :enum:`NGHTTP2_ERR_WOULDBLOCK`.  The"] # [doc = " |user_data| pointer is the third argument passed in to the call to"] # [doc = " `nghttp2_session_client_new()` or `nghttp2_session_server_new()`."] # [doc = ""] # [doc = " This callback is required if the application uses"] # [doc = " `nghttp2_session_recv()` to receive data from the remote endpoint."] # [doc = " If the application uses solely `nghttp2_session_mem_recv()`"] # [doc = " instead, this callback function is unnecessary."] # [doc = ""] # [doc = " To set this callback to :type:`nghttp2_session_callbacks`, use"] # [doc = " `nghttp2_session_callbacks_set_recv_callback()`."] pub type nghttp2_recv_callback = :: std :: option :: Option < unsafe extern "C" fn (session : * mut nghttp2_session , buf : * mut u8 , length : usize , flags : :: std :: os :: raw :: c_int , user_data : * mut :: std :: os :: raw :: c_void ,) -> isize , > ;
    };
}

nghttp2_recv_callback!()